import Header from './header';
import Status from './status';
import './App.css';
import { languages } from './languages';

chipsElem=languages.map(lan=>{
  <button style={{backgroundColor:lan.backgroundColor}}>{lan.name}</button>
})

function App() {
  return (
    <div className="App">
     <Header />
     <Status />
    </div>
  );
}

export default App;
